/**
 * QualityReport Component
 * Displays quality metrics including user satisfaction and first-time fix rates
 */

import React from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  PointElement,
  LineElement,
  Filler,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar, Line } from 'react-chartjs-2';
import type { QualityMetrics } from '../../../models/Report';
import styles from './QualityReport.module.css';

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  PointElement,
  LineElement,
  Filler,
  Tooltip,
  Legend
);

interface QualityReportProps {
  data: QualityMetrics;
}

export const QualityReport: React.FC<QualityReportProps> = ({ data }) => {
  const satisfactionChartData = {
    labels: ['5★', '4★', '3★', '2★', '1★'],
    datasets: [
      {
        label: 'Ratings',
        data: data.userSatisfaction.distribution,
        backgroundColor: ['#10b981', '#3b82f6', '#f59e0b', '#f97316', '#ef4444'],
      },
    ],
  };

  const satisfactionChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false,
      },
    },
    scales: {
      y: {
        beginAtZero: true,
      },
    },
  };

  const fixRateChartData = {
    labels: data.firstTimeFixRate.trend.map((point) => point.label),
    datasets: [
      {
        label: 'First Time Fix %',
        data: data.firstTimeFixRate.trend.map((point) => point.value),
        borderColor: '#10b981',
        backgroundColor: 'rgba(16, 185, 129, 0.1)',
        tension: 0.4,
        fill: true,
      },
    ],
  };

  const fixRateChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false,
      },
    },
    scales: {
      y: {
        beginAtZero: false,
        min: 60,
        max: 100,
      },
    },
  };

  const renderStars = () => {
    const rating = data.userSatisfaction.averageRating;
    const fullStars = Math.floor(rating);
    const hasHalfStar = rating % 1 >= 0.5;

    return (
      <div className={styles.stars}>
        {[...Array(fullStars)].map((_, i) => (
          <i key={`full-${i}`} className="fas fa-star"></i>
        ))}
        {hasHalfStar && <i className="fas fa-star-half-alt"></i>}
      </div>
    );
  };

  return (
    <div className={styles.container}>
      <div className={styles.cardsGrid}>
        {/* User Satisfaction */}
        <div className={styles.reportCard}>
          <div className={styles.cardHeader}>
            <h3 className={styles.cardTitle}>
              <i className="fas fa-smile"></i>
              User Satisfaction
            </h3>
          </div>
          <div className={styles.cardBody}>
            <div className={styles.ratingOverview}>
              {data.userSatisfaction.totalRatings > 0 ? (
                <>
                  <div className={styles.ratingScore}>
                    {data.userSatisfaction.averageRating.toFixed(1)}
                  </div>
                  {renderStars()}
                  <div className={styles.ratingCount}>
                    Dựa trên {data.userSatisfaction.totalRatings} đánh giá
                  </div>
                </>
              ) : (
                <div className={styles.noData}>
                  <i className="fas fa-star"></i>
                  <span>Chưa có đánh giá</span>
                </div>
              )}
            </div>
            <div className={styles.chartContainer}>
              <Bar data={satisfactionChartData} options={satisfactionChartOptions} />
            </div>
          </div>
        </div>

        {/* First Time Fix Rate */}
        <div className={styles.reportCard}>
          <div className={styles.cardHeader}>
            <h3 className={styles.cardTitle}>
              <i className="fas fa-check-double"></i>
              First Time Fix Rate
            </h3>
          </div>
          <div className={styles.cardBody}>
            <div className={styles.statsGrid}>
              <div className={`${styles.statCard} ${styles.green}`}>
                <div className={styles.statLabel}>Fixed First Time</div>
                <div className={styles.statValue}>
                  {data.firstTimeFixRate.fixedFirstTime}%
                </div>
              </div>
              <div className={`${styles.statCard} ${styles.orange}`}>
                <div className={styles.statLabel}>Tỉ lệ mở lại</div>
                <div className={styles.statValue}>
                  {data.firstTimeFixRate.reopenRate}%
                </div>
              </div>
            </div>
            {data.firstTimeFixRate.trend.length > 0 ? (
              <div className={styles.chartContainer}>
                <Line data={fixRateChartData} options={fixRateChartOptions} />
              </div>
            ) : (
              <div className={styles.noData}>
                <i className="fas fa-chart-line"></i>
                <span>Chưa có dữ liệu xu hướng</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};
