import React from 'react';
import { StatisticsPeriod } from '../../../models/Statistics';
import styles from './PeriodSelector.module.css';

interface PeriodSelectorProps {
  value: StatisticsPeriod;
  onChange: (period: StatisticsPeriod) => void;
}

export const PeriodSelector: React.FC<PeriodSelectorProps> = ({
  value,
  onChange,
}) => {
  const periods = [
    { value: StatisticsPeriod.Today, label: 'Hôm nay' },
    { value: StatisticsPeriod.Week, label: 'Tuần này' },
    { value: StatisticsPeriod.Month, label: 'Tháng này' },
    { value: StatisticsPeriod.Quarter, label: 'Quý này' },
    { value: StatisticsPeriod.Year, label: 'Năm nay' },
  ];

  return (
    <div className={styles.periodSelector}>
      <select
        className={styles.select}
        value={value}
        onChange={(e) => onChange(e.target.value as StatisticsPeriod)}
      >
        {periods.map((period) => (
          <option key={period.value} value={period.value}>
            {period.label}
          </option>
        ))}
      </select>
    </div>
  );
};
