/**
 * Badge generation helpers for Task Detail Page
 */

import { Badge } from '../../../components/common/Badge';
import { TaskPriority } from '../../../models/Task';

/**
 * Get priority badge with appropriate color.
 * @param priority  Task priority value (used for variant mapping only).
 * @param label     Human-readable label from BFF via useFormOptions('display-labels').
 */
export const getPriorityBadge = (priority: TaskPriority, label: string) => {
  switch (priority) {
    case TaskPriority.Critical:
      return <Badge variant="danger">{label}</Badge>;
    case TaskPriority.High:
      return <Badge variant="warning">{label}</Badge>;
    case TaskPriority.Medium:
      return <Badge variant="info">{label}</Badge>;
    case TaskPriority.Low:
      return <Badge variant="success">{label}</Badge>;
    default:
      return <Badge>{label}</Badge>;
  }
};

/**
 * Get status badge with appropriate color.
 * @param status  Task status value (used for variant mapping only).
 * @param label   Human-readable label from BFF via useFormOptions('display-labels').
 */
export const getStatusBadge = (status: string, label: string) => {
  switch (status) {
    case 'created':
      return <Badge variant="secondary">{label}</Badge>;
    case 'assigned':
      return <Badge variant="info">{label}</Badge>;
    case 'in_progress':
      return <Badge variant="primary">{label}</Badge>;
    case 'under_review':
      return <Badge variant="warning">{label}</Badge>;
    case 'completed':
      return <Badge variant="success">{label}</Badge>;
    case 'support_requested':
      return <Badge variant="warning">{label}</Badge>;
    case 'collab_assigned':
      return <Badge variant="info">{label}</Badge>;
    default:
      return <Badge>{label}</Badge>;
  }
};

/**
 * Get assignment strategy badge.
 * @param strategy  Assignment strategy value (used for variant mapping only).
 * @param label     Human-readable label from BFF via useFormOptions('display-labels').
 */
export const getAssignmentStrategyBadge = (strategy: string, label: string) => {
  switch (strategy) {
    case 'direct':
      return <Badge variant="info">{label}</Badge>;
    case 'pool':
      return <Badge variant="secondary">{label}</Badge>;
    case 'team':
      return <Badge variant="success">{label}</Badge>;
    default:
      return <Badge>{label}</Badge>;
  }
};

/**
 * Determine SLA status based on remaining time
 */
export const getSLAStatus = (slaRemaining?: number): 'safe' | 'warning' | 'danger' => {
  if (!slaRemaining) return 'safe';
  if (slaRemaining < 60) return 'danger';
  if (slaRemaining < 240) return 'warning';
  return 'safe';
};
