import React, { useState, useEffect, useRef, useCallback } from 'react';
import { userService } from '../../../services/user';
import { User } from '../../../models/User';
import styles from './UserMultiSearchInput.module.css';

/* ─── Public types ─────────────────────────────────────────────────────── */

export interface SelectedUser {
  userId: string;
  staffId: string;
  fullName: string;
}

export interface UserMultiSearchInputProps {
  /** Currently selected users */
  value: SelectedUser[];
  /** Called whenever the selected set changes */
  onChange: (users: SelectedUser[]) => void;
  /** User IDs to hide from the dropdown (e.g. current assignee, already-active collaborators) */
  excludeUserIds?: string[];
  /** Show department filter dropdown. Default true. */
  showDepartmentFilter?: boolean;
  /** Pre-selected department ID */
  departmentId?: string;
  /** Label shown above the input */
  label?: string;
  /** Placeholder for the search input */
  placeholder?: string;
  required?: boolean;
  disabled?: boolean;
  /** Maximum users that can be selected (0 = unlimited) */
  maxSelection?: number;
  /** Render the list inline (in normal flow) instead of as an absolute dropdown.
   *  Use this when the component is inside a scrollable container (e.g. Slideout). */
  inline?: boolean;
  /** Inline error message */
  error?: string;
}

const PAGE_SIZE = 20;

export const UserMultiSearchInput: React.FC<UserMultiSearchInputProps> = ({
  value,
  onChange,
  excludeUserIds = [],
  showDepartmentFilter = true,
  departmentId: propDepartmentId,
  label = 'Chọn người dùng',
  placeholder = 'Nhập mã hoặc tên để tìm...',
  required = false,
  disabled = false,
  maxSelection = 0,
  inline = false,
  error,
}) => {
  const [term, setTerm] = useState('');
  const [deptId, setDeptId] = useState(propDepartmentId ?? '');
  const [departments, setDepartments] = useState<{ id: string; name: string }[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const [users, setUsers] = useState<User[]>([]);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(false);

  // Pending selections — committed only on confirm / close
  const [pending, setPending] = useState<SelectedUser[]>(value);
  const pendingIds = new Set(pending.map((u) => u.userId));
  const [showSelectedOnly, setShowSelectedOnly] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const sentinelRef = useRef<HTMLDivElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const searchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const excludeSet = new Set(excludeUserIds);
  const isAtMax = maxSelection > 0 && pending.length >= maxSelection;

  // Sync pending when parent value changes externally (e.g. reset)
  useEffect(() => {
    if (!isOpen) setPending(value);
  }, [value, isOpen]);

  // ── Load departments ────────────────────────────────────────────────────
  useEffect(() => {
    if (!showDepartmentFilter) return;
    userService
      .getUsers({ pageSize: 200 })
      .then((res) => {
        const deptMap = new Map<string, string>();
        res.items.forEach((u) => {
          if (u.departmentId && u.departmentName) {
            deptMap.set(u.departmentId, u.departmentName);
          }
        });
        setDepartments(
          Array.from(deptMap.entries()).map(([id, name]) => ({ id, name })),
        );
      })
      .catch(() => {});
  }, [showDepartmentFilter]);

  // ── Fetch users (reset or next page) ────────────────────────────────────
  const fetchUsers = useCallback(
    async (searchTerm: string, departmentId: string, resetPage: boolean) => {
      setLoading(true);
      const nextPage = resetPage ? 1 : page + 1;
      try {
        const res = await userService.getUsers({
          search: searchTerm || undefined,
          departmentId: departmentId || undefined,
          page: nextPage,
          pageSize: PAGE_SIZE,
        });
        setUsers((prev) => (resetPage ? res.items : [...prev, ...res.items]));
        setPage(res.page);
        setTotalPages(res.totalPages);
      } catch {
        // ignore
      } finally {
        setLoading(false);
      }
    },
    [page],
  );

  // Debounced search when term or dept changes
  useEffect(() => {
    if (!isOpen) return;
    if (searchTimerRef.current) clearTimeout(searchTimerRef.current);
    searchTimerRef.current = setTimeout(() => {
      fetchUsers(term, deptId, true);
    }, 300);
    return () => {
      if (searchTimerRef.current) clearTimeout(searchTimerRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [term, deptId, isOpen]);

  // ── IntersectionObserver for infinite scroll ────────────────────────────
  useEffect(() => {
    if (!sentinelRef.current) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting && !loading && page < totalPages) {
          fetchUsers(term, deptId, false);
        }
      },
      { root: dropdownRef.current, threshold: 0.1 },
    );
    observer.observe(sentinelRef.current);
    return () => observer.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loading, page, totalPages, isOpen]);

  // ── Close dropdown on outside click → auto-confirm ──────────────────────
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        if (isOpen) confirmAndClose();
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, pending]);

  // ── Handlers ────────────────────────────────────────────────────────────
  const openDropdown = () => {
    if (disabled) return;
    setPending(value); // snapshot current value as pending
    setShowSelectedOnly(false);
    setIsOpen(true);
  };

  const confirmAndClose = () => {
    onChange(pending);
    setTerm('');
    setIsOpen(false);
  };

  const handleTermChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setTerm(e.target.value);
    if (!isOpen) openDropdown();
  };

  const handleFocus = () => {
    if (!isOpen) openDropdown();
  };

  const handleToggle = (user: User) => {
    if (pendingIds.has(user.id)) {
      setPending((prev) => prev.filter((u) => u.userId !== user.id));
    } else {
      if (isAtMax) return;
      setPending((prev) => [
        ...prev,
        {
          userId: user.id,
          staffId: user.staffId ?? user.username,
          fullName: user.fullName,
        },
      ]);
    }
  };

  const handleRemoveChip = (userId: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    // Remove from committed value directly (when dropdown is closed)
    onChange(value.filter((u) => u.userId !== userId));
  };

  const handleDeptChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setDeptId(e.target.value);
  };

  // Filter dropdown results: exclude hidden ids, optionally show selected only
  const visibleUsers = users
    .filter((u) => !excludeSet.has(u.id))
    .filter((u) => !showSelectedOnly || pendingIds.has(u.id));

  // ── Render ──────────────────────────────────────────────────────────────
  return (
    <div
      className={`${styles.container} ${error ? styles.hasError : ''} ${disabled ? styles.disabled : ''}`}
      ref={containerRef}
    >
      {label && (
        <label className={styles.label}>
          {label}
          {required && <span className={styles.required}> *</span>}
        </label>
      )}

      {/* Input box — shows chips (collapsed) or search input (open) */}
      <div
        className={`${styles.inputBox} ${isOpen ? styles.inputBoxOpen : ''}`}
        onClick={() => { if (!isOpen && !disabled) openDropdown(); }}
      >
        {/* Inline chips (shown when dropdown is CLOSED and there are selections) */}
        {!isOpen && value.length > 0 && (
          <div className={styles.chipArea}>
            {value.map((u) => (
              <span key={u.userId} className={styles.chip}>
                <span className={styles.chipName}>{u.fullName}</span>
                {!disabled && (
                  <button
                    type="button"
                    className={styles.chipRemove}
                    onClick={(e) => handleRemoveChip(u.userId, e)}
                    title="Bỏ chọn"
                  >
                    ✕
                  </button>
                )}
              </span>
            ))}
          </div>
        )}

        {/* Placeholder when no selection and closed */}
        {!isOpen && value.length === 0 && (
          <span className={styles.inputPlaceholder}>{placeholder}</span>
        )}

        {/* Search input (shown when dropdown is OPEN) */}
        {isOpen && (
          <input
            ref={inputRef}
            type="text"
            className={styles.searchInput}
            value={term}
            onChange={handleTermChange}
            onFocus={handleFocus}
            placeholder={isAtMax ? `Đã chọn tối đa ${maxSelection} người` : placeholder}
            disabled={disabled || isAtMax}
            autoComplete="off"
            autoFocus
          />
        )}

        <span className={styles.inputIcon}>
          <i className={`fas ${isOpen ? 'fa-search' : 'fa-chevron-down'}`} />
        </span>
      </div>

      {/* Dropdown panel */}
      {isOpen && !disabled && (
        <div className={`${styles.dropdown} ${inline ? styles.dropdownInline : ''}`}>
          {/* Department filter */}
          {showDepartmentFilter && (
            <div className={styles.deptFilter}>
              <select
                className={styles.deptSelect}
                value={deptId}
                onChange={handleDeptChange}
                disabled={disabled}
              >
                <option value="">Tất cả phòng ban</option>
                {departments.map((d) => (
                  <option key={d.id} value={d.id}>
                    {d.name}
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* User list */}
          <div className={styles.listScroll} ref={dropdownRef}>
            {loading && users.length === 0 ? (
              <div className={styles.loadingRow}>
                <i className="fas fa-spinner fa-spin" /> Đang tải...
              </div>
            ) : visibleUsers.length === 0 ? (
              <div className={styles.emptyRow}>Không tìm thấy kết quả</div>
            ) : (
              <>
                <div className={styles.userList}>
                  {visibleUsers.map((u) => {
                    const isSelected = pendingIds.has(u.id);
                    return (
                      <button
                        key={u.id}
                        type="button"
                        className={`${styles.userCard} ${isSelected ? styles.selected : ''}`}
                        onClick={() => handleToggle(u)}
                        disabled={!isSelected && isAtMax}
                      >
                        <div className={styles.checkbox}>
                          {isSelected && <i className="fas fa-check" />}
                        </div>

                        <div className={styles.userInfo}>
                          {u.staffId && (
                            <span className={styles.staffBadge}>{u.staffId}</span>
                          )}
                          <span className={styles.userName}>{u.fullName}</span>
                        </div>

                        <span className={styles.userMeta}>
                          {u.departmentName && (
                            <span className={styles.metaDept}>
                              <i className="fas fa-building" /> {u.departmentName}
                            </span>
                          )}
                        </span>
                      </button>
                    );
                  })}
                </div>

                {/* Infinite-scroll sentinel */}
                {page < totalPages && (
                  <div ref={sentinelRef} className={styles.sentinel}>
                    {loading && (
                      <span className={styles.loadMoreHint}>
                        <i className="fas fa-spinner fa-spin" /> Đang tải thêm...
                      </span>
                    )}
                  </div>
                )}
              </>
            )}
          </div>

          {/* Dropdown footer — filter toggle + confirm button */}
          <div className={styles.dropdownFooter}>
            <label className={styles.filterToggle}>
              <input
                type="checkbox"
                checked={showSelectedOnly}
                onChange={(e) => setShowSelectedOnly(e.target.checked)}
                className={styles.filterCheckbox}
              />
              <span>
                {pending.length > 0
                  ? `Đã chọn ${pending.length} người`
                  : 'Chưa chọn người nào'}
              </span>
            </label>
            <button
              type="button"
              className={styles.confirmBtn}
              onClick={confirmAndClose}
            >
              <i className="fas fa-check" /> Xác nhận
            </button>
          </div>
        </div>
      )}

      {error && <span className={styles.errorMsg}>{error}</span>}
    </div>
  );
};
