/**
 * IncidentPrintModal
 *
 * Desktop  : modal with 3 doc checkboxes + live A4 preview + print trigger.
 * Native mobile (Android / iOS):
 *   - Show doc-selection modal (NO preview — mobile browsers don't render it well)
 *   - On confirm → trigger browser print/save-as-PDF dialog
 */
import React, { useEffect, useRef, useState } from 'react';
import { useReactToPrint } from 'react-to-print';
import { MedicalIncident } from '../../../models/MedicalIncident';
import { Button } from '../../common/Button';
import { useResponsive } from '../../../hooks/useResponsive';
import { PrintableIncidentDocs, PrintSelection } from './PrintableIncidentDocs';
import styles from './IncidentPrintModal.module.css';

interface Props {
  isOpen:   boolean;
  onClose:  () => void;
  incident: MedicalIncident;
}

const DEFAULT_SELECTION: PrintSelection = {
  baoCao:   true,
  phanTich: false,
  bienBan:  false,
};

const ALL_SELECTED: PrintSelection = {
  baoCao:   true,
  phanTich: true,
  bienBan:  true,
};

/** Detect real Android / iOS device (not just small screen on desktop) */
const isNativeMobileDevice = (): boolean => {
  if (typeof navigator === 'undefined') return false;
  return /android|iphone|ipad|ipod/i.test(navigator.userAgent);
};

const PAGE_STYLE = `
  /*
   * Vietnamese Government Document Margin Standard (Nghị định 30/2020/NĐ-CP)
   * Lề trên (Top)   : 20mm
   * Lề dưới (Bottom): 20mm
   * Lề trái (Left)  : 30mm
   * Lề phải (Right) : 15mm
   *
   * Using @page margin (NOT .document padding) so the browser
   * preserves margins on EVERY physical page when content breaks.
   */
  @page {
    size: A4 portrait;
    margin: 20mm 15mm 20mm 30mm;
    background: white;
  }
  @media print {
    html, body {
      margin: 0 !important;
      padding: 0 !important;
      overflow: visible !important;
      height: auto !important;
      width: 100% !important;
      background: white !important;
      background-color: white !important;
    }
    body > div {
      zoom: 1 !important;
      background: white !important;
    }
  }
`;

export const IncidentPrintModal: React.FC<Props> = ({ isOpen, onClose, incident }) => {
  const { isMobile } = useResponsive();
  const [sel, setSel] = useState<PrintSelection>(DEFAULT_SELECTION);
  const printRef = useRef<HTMLDivElement>(null);

  // true when running on a real Android / iOS device
  const [nativeMobile] = useState(() => isNativeMobileDevice());

  // Calculate zoom to fit A4 (794px) into the preview container
  const previewScrollRef = useRef<HTMLDivElement>(null);
  const [zoom, setZoom] = useState(0.68);

  useEffect(() => {
    const calc = () => {
      if (previewScrollRef.current) {
        const containerW = previewScrollRef.current.clientWidth - 32;
        const a4px = 794;
        setZoom(Math.min(1, containerW / a4px));
      }
    };
    calc();
    const ro = new ResizeObserver(calc);
    if (previewScrollRef.current) ro.observe(previewScrollRef.current);
    return () => ro.disconnect();
  }, [isOpen]);

  const handlePrint = useReactToPrint({
    contentRef: printRef,
    documentTitle: `SuCoYKhoa_${incident.idCode || 'doc'}`,
    pageStyle: PAGE_STYLE,
    onAfterPrint: () => {
      // Desktop: close after print dialog dismissed
      if (!nativeMobile && !isMobile) return;
      onClose();
    },
  });

  /**
   * Android/iOS: react-to-print uses an iframe → Android Chrome ignores it and
   * prints the parent page instead.  Fix: clone all CSS from the current document
   * into a new window, then call window.print() on that window.
   */
  const handleMobilePrint = () => {
    const content = printRef.current;
    if (!content) return;

    // Collect all CSS rules from every loaded stylesheet
    const allCss = Array.from(document.styleSheets)
      .map((sheet) => {
        try {
          return Array.from(sheet.cssRules).map((r) => r.cssText).join('\n');
        } catch {
          // Cross-origin sheets (CDN) — try <link> href instead
          return '';
        }
      })
      .join('\n');

    // Also grab any <link rel="stylesheet"> hrefs for font-awesome / google fonts etc.
    const linkTags = Array.from(document.querySelectorAll<HTMLLinkElement>('link[rel="stylesheet"]'))
      .map((l) => `<link rel="stylesheet" href="${l.href}">`)
      .join('\n');

    const win = window.open('', '_blank');
    if (!win) {
      // Popup blocked → fallback to iframe-based react-to-print
      handlePrint();
      return;
    }

    win.document.write(`<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>SuCoYKhoa_${incident.idCode || 'doc'}</title>
  ${linkTags}
  <style>${allCss}</style>
  <style>${PAGE_STYLE}</style>
</head>
<body>${content.innerHTML}</body>
</html>`);
    win.document.close();
    // Small delay to let fonts / images load before print dialog
    setTimeout(() => {
      win.focus();
      win.print();
      // Close the helper tab after the dialog closes
      win.addEventListener('afterprint', () => { win.close(); onClose(); });
    }, 400);
  };

  if (!isOpen) return null;

  const noneSelected = !sel.baoCao && !sel.phanTich && !sel.bienBan;
  const allSelected  =  sel.baoCao &&  sel.phanTich &&  sel.bienBan;

  const toggle = (key: keyof PrintSelection) =>
    setSel((prev) => ({ ...prev, [key]: !prev[key] }));

  const toggleAll = () =>
    setSel(allSelected ? { baoCao: false, phanTich: false, bienBan: false } : ALL_SELECTED);

  // ── Shared doc-selection list ────────────────────────────────────────
  const docSelectionUI = (
    <div className={styles.body}>
      <p className={styles.hint}>
        Chọn tài liệu muốn {nativeMobile ? 'tải PDF' : 'in hoặc lưu thành PDF'} (A4).
        <br /><strong>{incident.idCode}</strong>
      </p>

      <label className={styles.selectAll}>
        <input type="checkbox" checked={allSelected} onChange={toggleAll} />
        Chọn tất cả
      </label>

      <hr className={styles.divider} />

      <label className={`${styles.docOption} ${sel.baoCao ? styles.docOptionActive : ''}`}>
        <input type="checkbox" checked={sel.baoCao} onChange={() => toggle('baoCao')} />
        <div className={styles.docOptionContent}>
          <span className={styles.docOptionTitle}>
            <i className="fas fa-file-alt" style={{ marginRight: 6, color: '#3b82f6' }} />
            Báo Cáo Sự Cố Y Khoa
          </span>
          <span className={styles.docOptionDesc}>
            Mẫu TT 43/2018/TT-BYT — Thông tin sự cố, người bệnh, thông báo, phân loại
          </span>
        </div>
      </label>

      <label className={`${styles.docOption} ${sel.phanTich ? styles.docOptionActive : ''}`}>
        <input type="checkbox" checked={sel.phanTich} onChange={() => toggle('phanTich')} />
        <div className={styles.docOptionContent}>
          <span className={styles.docOptionTitle}>
            <i className="fas fa-search" style={{ marginRight: 6, color: '#8b5cf6' }} />
            Tìm Hiểu Và Phân Tích Sự Cố
          </span>
          <span className={styles.docOptionDesc}>
            Mô tả chi tiết, phân loại sự cố 11 nhóm, nguyên nhân 4 nhóm
          </span>
        </div>
      </label>

      <label className={`${styles.docOption} ${sel.bienBan ? styles.docOptionActive : ''}`}>
        <input type="checkbox" checked={sel.bienBan} onChange={() => toggle('bienBan')} />
        <div className={styles.docOptionContent}>
          <span className={styles.docOptionTitle}>
            <i className="fas fa-gavel" style={{ marginRight: 6, color: '#f59e0b' }} />
            Biên Bản Đánh Giá Sự Cố Y Khoa
          </span>
          <span className={styles.docOptionDesc}>
            Đánh giá nhóm chuyên gia, mức độ tổn thương, kết luận &amp; chữ ký
          </span>
        </div>
      </label>
    </div>
  );

  // ── Native mobile layout: selection only, no preview ─────────────────
  if (nativeMobile || isMobile) {
    return (
      <>
        <div className={styles.overlay} onClick={onClose}>
          <div className={`${styles.modal} ${styles.modalMobile}`} onClick={(e) => e.stopPropagation()}>
            <div className={styles.header}>
              <h2 className={styles.title}>
                <i className="fas fa-file-pdf" /> Tải PDF
              </h2>
              <button className={styles.closeBtn} onClick={onClose} aria-label="Đóng">
                <i className="fas fa-times" />
              </button>
            </div>

            {docSelectionUI}

            <div className={styles.footer}>
              <Button variant="secondary" onClick={onClose}>Hủy</Button>
              <Button
                variant="primary"
                onClick={() => handleMobilePrint()}
                disabled={noneSelected}
              >
                <i className="fas fa-download" /> Tải PDF
              </Button>
            </div>
          </div>
        </div>

        {/* Hidden print target */}
        <div className={styles.printHidden}>
          <PrintableIncidentDocs ref={printRef} incident={incident} selection={sel} />
        </div>
      </>
    );
  }

  // ── Desktop layout: two-pane with live preview ────────────────────────
  return (
    <>
      <div className={styles.overlay} onClick={onClose}>
        <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
          {/* Header */}
          <div className={styles.header}>
            <h2 className={styles.title}>
              <i className="fas fa-file-pdf" /> Tải PDF / In tài liệu
            </h2>
            <button className={styles.closeBtn} onClick={onClose} aria-label="Đóng">
              <i className="fas fa-times" />
            </button>
          </div>

          {/* Two-pane body */}
          <div className={styles.twoPane}>
            {/* Left: selection */}
            <div className={styles.leftPane}>
              {docSelectionUI}

              {/* Left-pane footer actions */}
              <div className={styles.footer}>
                <Button variant="secondary" onClick={onClose}>Hủy</Button>
                <Button
                  variant="primary"
                  onClick={() => handlePrint()}
                  disabled={noneSelected}
                >
                  <i className="fas fa-print" /> In / Lưu PDF
                </Button>
              </div>
            </div>

            {/* Right: live A4 preview */}
            <div className={styles.rightPane}>
              <div className={styles.previewLabel}>
                <i className="fas fa-eye" style={{ marginRight: 6 }} /> Xem trước
              </div>
              <div className={styles.previewScroll} ref={previewScrollRef}>
                {noneSelected ? (
                  <div style={{ padding: 40, color: '#9ca3af', textAlign: 'center', fontFamily: 'sans-serif', fontSize: 14 }}>
                    <i className="fas fa-file-pdf" style={{ fontSize: 40, marginBottom: 12, display: 'block' }} />
                    Chọn ít nhất 1 tài liệu để xem trước
                  </div>
                ) : (
                  <div style={{ zoom: zoom }}>
                    <PrintableIncidentDocs
                      incident={incident}
                      selection={sel}
                    />
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Hidden print target — full resolution, no scaling */}
      <div className={styles.printHidden}>
        <PrintableIncidentDocs
          ref={printRef}
          incident={incident}
          selection={sel}
        />
      </div>
    </>
  );
};
