import React, { useState, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { triageTicket } from '../../../store/slices/ticketsSlice';
import { addToast } from '../../../store/slices/uiSlice';
import { UUID } from '../../../models/common';
import { Slideout } from '../../common/Slideout';
import { Select } from '../../common/Select';
import { useFormOptions } from '../../../hooks/useFormOptions';
import { TextArea } from '../../common/TextArea';
import { StatusBadge } from '../../common/StatusBadge';
import { FormActions } from '../../common/FormActions';
import styles from './TriageTicketModal.module.css';

export interface TriageTicketModalProps {
  isOpen: boolean;
  ticketId: UUID;
  onClose: () => void;
  onSuccess?: () => void;
}

export const TriageTicketModal: React.FC<TriageTicketModalProps> = ({
  isOpen,
  ticketId,
  onClose,
  onSuccess,
}) => {
  const dispatch = useAppDispatch();
  const ticket = useAppSelector((state) => state.tickets.selectedTicket);
  const [action, setAction] = useState<'accept' | 'reject' | 'request_info' | ''>('');
  const [priority, setPriority] = useState<string>('');
  const [reason, setReason] = useState('');
  const [loading, setLoading] = useState(false);
  const { ticketPriorityOptions } = useFormOptions('edit-ticket');

  useEffect(() => {
    if (isOpen && ticket) {
      setPriority(ticket.priority);
      setAction('');
      setReason('');
    }
  }, [isOpen, ticket]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!action) {
      dispatch(
        addToast({
          message: 'Vui lòng chọn hành động',
          type: 'error',
        })
      );
      return;
    }

    if ((action === 'reject' || action === 'request_info') && !reason.trim()) {
      dispatch(
        addToast({
          message: 'Vui lòng nhập lý do',
          type: 'error',
        })
      );
      return;
    }

    setLoading(true);

    try {
      await dispatch(
        triageTicket({
          ticketId,
          action,
          priority: priority || undefined,
          reason: reason.trim() || undefined,
        })
      ).unwrap();

      const actionMessages = {
        accept: 'Duyệt phiếu yêu cầu thành công',
        reject: 'Từ chối phiếu yêu cầu thành công',
        request_info: 'Yêu cầu bổ sung thông tin thành công',
      };

      dispatch(
        addToast({
          message: actionMessages[action],
          type: 'success',
        })
      );

      handleCancel();
      if (onSuccess) {
        onSuccess();
      }
    } catch (error: any) {
      dispatch(
        addToast({
          message: error.message || 'Không thể xử lý phiếu yêu cầu',
          type: 'error',
        })
      );
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    setAction('');
    setPriority('');
    setReason('');
    onClose();
  };

  const isReasonRequired = action === 'reject' || action === 'request_info';

  if (!ticket) {
    return null;
  }

  const getSubmitButtonLabel = () => {
    if (action === 'accept') return 'Chấp Nhận Phiếu';
    if (action === 'reject') return 'Từ Chối Phiếu';
    if (action === 'request_info') return 'Gửi Yêu Cầu';
    return 'Chọn Hành Động';
  };

  const handleConfirmTriage = () => {
    handleSubmit(new Event('submit') as any);
  };

  return (
    <Slideout 
      isOpen={isOpen} 
      onClose={handleCancel} 
      title="Phân Loại Phiếu Yêu Cầu"
      width="700px"
      footer={{
        leftLabel: 'Hủy',
        leftAction: handleCancel,
        leftDisabled: loading,
        rightLabel: getSubmitButtonLabel(),
        rightAction: handleConfirmTriage,
        rightDisabled: !action || loading,
      }}
    >
      <form onSubmit={handleSubmit} className={styles.form}>
        {/* Ticket Summary */}
        <div className={styles.ticketSummary}>
          <div className={styles.summaryRow}>
            <span className={styles.label}>Tiêu đề:</span>
            <span className={styles.value}>{ticket.title}</span>
          </div>
          <div className={styles.summaryRow}>
            <span className={styles.label}>Người tạo:</span>
            <span className={styles.value}>{ticket.createdByName}</span>
          </div>
          <div className={styles.summaryRow}>
            <span className={styles.label}>Trạng thái:</span>
            <StatusBadge status={ticket.status} compact />
          </div>
          <div className={styles.summaryRow}>
            <span className={styles.label}>Mô tả:</span>
            <p className={styles.description}>{ticket.description}</p>
          </div>
        </div>

        {/* Priority Adjustment */}
        <div className={styles.formGroup}>
          <label htmlFor="priority" className={styles.formLabel}>
            Điều Chỉnh Độ Ưu Tiên
          </label>
          <Select
            id="priority"
            value={priority}
            onChange={(e) => setPriority(e.target.value)}
            options={ticketPriorityOptions}
            placeholder="Chọn độ ưu tiên"
          />
          <span className={styles.hint}>Có thể thay đổi độ ưu tiên khi phân loại</span>
        </div>

        {/* Action Buttons */}
        <div className={styles.actionSection}>
          <p className={styles.actionTitle}>Chọn Hành Động:</p>
          <FormActions align="stretch">
            <button
              type="button"
              className={`${styles.actionButton} ${styles.accept} ${action === 'accept' ? styles.active : ''}`}
              onClick={() => setAction('accept')}
            >
              <i className="fas fa-check-circle"></i>
              <span>Chấp Nhận</span>
              <small>Duyệt phiếu và phân công</small>
            </button>
            <button
              type="button"
              className={`${styles.actionButton} ${styles.requestInfo} ${action === 'request_info' ? styles.active : ''}`}
              onClick={() => setAction('request_info')}
            >
              <i className="fas fa-info-circle"></i>
              <span>Yêu Cầu Thông Tin</span>
              <small>Cần bổ sung thông tin</small>
            </button>
            <button
              type="button"
              className={`${styles.actionButton} ${styles.reject} ${action === 'reject' ? styles.active : ''}`}
              onClick={() => setAction('reject')}
            >
              <i className="fas fa-times-circle"></i>
              <span>Từ Chối</span>
              <small>Không chấp nhận phiếu</small>
            </button>
          </FormActions>
        </div>

        {/* Reason Input (conditional) */}
        {action && (action === 'reject' || action === 'request_info') && (
          <div className={styles.formGroup}>
            <label htmlFor="reason" className={styles.formLabel}>
              Lý Do {isReasonRequired && <span className={styles.required}>*</span>}
            </label>
            <TextArea
              id="reason"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder={
                action === 'reject'
                  ? 'Nhập lý do từ chối...'
                  : 'Nhập thông tin cần bổ sung...'
              }
              rows={4}
              required={isReasonRequired}
            />
          </div>
        )}
      </form>
    </Slideout>
  );
};
