import React, { useState, useMemo } from 'react';
import { Tabs, Tab, Select, SelectOption } from '../../../../components/common';
import { ApprovalStatus, ApprovalType } from '../../../../models/Approval';
import { useResponsive } from '../../../../hooks/useResponsive';
import styles from './ApprovalsFilters.module.css';

export interface ApprovalsFiltersProps {
  activeTab: ApprovalStatus;
  onTabChange: (tab: ApprovalStatus) => void;
  typeFilter: string;
  onTypeChange: (type: string) => void;
  pendingCount: number;
  approvedTodayCount: number;
  rejectedTodayCount: number;
}

const TYPE_OPTIONS: SelectOption[] = [
  { value: 'all',                              label: 'Tất cả loại' },
  { value: ApprovalType.TaskClosure,           label: 'Đóng công việc' },
  { value: ApprovalType.TaskCreation,          label: 'Tạo công việc' },
  { value: ApprovalType.TaskReassignment,      label: 'Chuyển giao' },
  { value: ApprovalType.ResourceRequest,       label: 'Yêu cầu tài nguyên' },
  { value: ApprovalType.SupportRequest,        label: 'Yêu cầu hỗ trợ' },
  { value: ApprovalType.Other,                 label: 'Khác' },
];

export const ApprovalsFilters: React.FC<ApprovalsFiltersProps> = ({
  activeTab,
  onTabChange,
  typeFilter,
  onTypeChange,
  pendingCount,
  approvedTodayCount,
  rejectedTodayCount,
}) => {
  const { isMobile } = useResponsive();
  const [isExpanded, setIsExpanded] = useState(false);

  const tabs: Tab[] = useMemo(
    () => [
      {
        id: ApprovalStatus.Pending,
        label: 'Chờ phê duyệt',
        badge: pendingCount,
        badgeColor: 'warning' as const,
      },
      {
        id: ApprovalStatus.Approved,
        label: 'Đã chấp nhận',
        badge: approvedTodayCount,
        badgeColor: 'success' as const,
      },
      {
        id: ApprovalStatus.Rejected,
        label: 'Đã từ chối',
        badge: rejectedTodayCount,
        badgeColor: 'gray' as const,
      },
    ],
    [pendingCount, approvedTodayCount, rejectedTodayCount]
  );

  const hasActiveFilters = typeFilter !== 'all';
  const activeFilterCount = hasActiveFilters ? 1 : 0;

  const handleTypeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onTypeChange(e.target.value);
  };

  const handleClear = () => {
    onTypeChange('all');
    setIsExpanded(false);
  };

  // ─── Mobile ────────────────────────────────────────────────────────────────
  if (isMobile) {
    return (
      <>
        {isExpanded && <div className={styles.filterBackdrop} onClick={() => setIsExpanded(false)} />}
        <div className={styles.container}>
          {/* Tabs always visible on mobile */}
          <Tabs
            tabs={tabs}
            activeTab={activeTab}
            onTabChange={(id) => onTabChange(id as ApprovalStatus)}
            variant="default"
          />
          <div className={styles.mobileFilterRow}>
            <div className={styles.filterDropdownWrapper}>
              <button
                className={styles.filterToggle}
                onClick={() => setIsExpanded((v) => !v)}
                aria-expanded={isExpanded}
                type="button"
              >
                <i className="fas fa-filter" />
                <span>Lọc</span>
                {activeFilterCount > 0 && (
                  <span className={styles.filterBadge}>{activeFilterCount}</span>
                )}
                <i className={`fas fa-chevron-${isExpanded ? 'up' : 'down'}`} />
              </button>
              {isExpanded && (
                <div className={styles.mobileFilters}>
                  <Select
                    value={typeFilter}
                    onChange={handleTypeChange}
                    options={TYPE_OPTIONS}
                    fullWidth
                  />
                  {hasActiveFilters && (
                    <button className={styles.clearFiltersButton} onClick={handleClear} type="button">
                      <i className="fas fa-times-circle" />
                      <span>Xóa bộ lọc</span>
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      </>
    );
  }

  // ─── Desktop ───────────────────────────────────────────────────────────────
  return (
    <div className={styles.container}>
      <Tabs
        tabs={tabs}
        activeTab={activeTab}
        onTabChange={(id) => onTabChange(id as ApprovalStatus)}
        variant="default"
      />
      <div className={styles.desktopFilters}>
        <Select
          value={typeFilter}
          onChange={handleTypeChange}
          options={TYPE_OPTIONS}
          size="small"
        />
        {hasActiveFilters && (
          <button className={styles.clearFiltersButtonDesktop} onClick={handleClear} type="button">
            <i className="fas fa-times-circle" />
            <span>Xóa bộ lọc</span>
          </button>
        )}
      </div>
    </div>
  );
};
