import React from 'react';
import { Ticket } from '../../../../models/Ticket';
import { SLABadge, formatSLATime, getSLAStatus } from '../../../../components/common/SLABadge';
import { TwoLineTable, TwoLineTableColumn, TwoLineTableRow } from '../../../../components/common/TwoLineTable';
import { TicketActions } from '../../../../components/tickets/TicketActions';
import styles from './TicketTable.module.css';
import { useResponsive } from '@/hooks/useResponsive';

export interface TicketTableProps {
  tickets: Ticket[];
  loading: boolean;
  onView: (ticket: Ticket) => void;
  onEdit: (ticket: Ticket) => void;
  onAssign: (ticket: Ticket) => void;
  onTriage: (ticket: Ticket) => void;
}

export const TicketTable: React.FC<TicketTableProps> = ({
  tickets,
  loading,
  onView,
  onEdit,
  onAssign,
  onTriage,
}) => {
  const { isMobile } = useResponsive();

  const getPriorityIcon = (priority: string) => {
    switch (priority.toLowerCase()) {
      case 'emergency':
        return 'fa-bolt';
      case 'high':
        return 'fa-arrow-up';
      case 'medium':
        return 'fa-equals';
      case 'low':
        return 'fa-arrow-down';
      default:
        return 'fa-circle';
    }
  };

  const getPriorityLabel = (priority: string) => {
    switch (priority.toLowerCase()) {
      case 'emergency':
        return 'Khẩn cấp';
      case 'high':
        return 'Cao';
      case 'medium':
        return 'Trung bình';
      case 'low':
        return 'Thấp';
      default:
        return priority;
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status.toLowerCase()) {
      case 'new':
        return 'Mới';
      case 'submitted':
        return 'Đã gửi';
      case 'pending':
        return 'Chờ xử lý';
      case 'in_progress':
        return 'Đang xử lý';
      case 'under_review':
        return 'Đang xem xét';
      case 'resolved':
        return 'Đã hoàn thành';
      case 'completed':
        return 'Hoàn thành';
      case 'closed':
        return 'Đã đóng';
      case 'rejected':
        return 'Từ chối';
      default:
        return status;
    }
  };

  // Define table columns (removed actions column since it's in overlay)
  const columns: TwoLineTableColumn[] = [
    { key: 'department', label: 'Phòng ban', width: '20%' },
    { key: 'priority', label: 'Ưu tiên', width: '20%' },
    { key: 'sla', label: 'SLA', width: '20%' },
    { key: 'assignee', label: 'Người xử lý', width: '40%' },
  ];

  // Transform tickets to table rows
  const rows: TwoLineTableRow<Ticket>[] = tickets.map((ticket) => {
    const slaStatus = getSLAStatus(ticket.sla.percentage, ticket.sla.breached);
    const slaTime = formatSLATime(ticket.sla.remainingMinutes);

    return {
      id: ticket.id,
      data: ticket,
      idElement: (
        <span className={styles.line1CellItem}>
          <strong className={styles.ticketId}>{ticket.idCode ?? ticket.id}</strong>
        </span>
      ),
      line1Content: (
        <>
          <span className={`${styles.line1CellItem} ${styles.ticketTitle}`}>
            {ticket.title}
          </span>
          <span className={styles.line1CellItem}>
            <span className={`${styles.status} ${styles[`status-${ticket.status.toLowerCase()}`]}`}>
              {getStatusLabel(ticket.status)}
            </span>
          </span>
        </>
      ),
      line2Cells: [
        // Department
        <span className={styles.department}>{ticket.departmentName}</span>,
        // Priority
        <span className={`${styles.priority} ${styles[`priority-${ticket.priority.toLowerCase()}`]}`}>
          <i className={`fas ${getPriorityIcon(ticket.priority)}`}></i>
          {getPriorityLabel(ticket.priority)}
        </span>,
        // SLA
        <SLABadge status={slaStatus} timeRemaining={slaTime} />,
        // Assignee
        ticket.assigneeId ? (
          <div className={styles.assignee}>
            <span className={styles.avatar}>
              {ticket.assigneeName?.charAt(0).toUpperCase()}
            </span>
            <span className={styles.assigneeName}>{ticket.assigneeName}</span>
          </div>
        ) : (
          <span className={styles.unassigned}>Chưa gán</span>
        ),
      ],
      actionsContent: (
        <div className={styles.actionsWrapper}>
          <TicketActions
            ticket={ticket}
            variant="list"
            size="md"
            showLabels={true}
            onView={onView}
            onEdit={onEdit}
            onAssign={onAssign}
            onTriage={onTriage}
          />
        </div>
      ),
    };
  });

  return (
    <TwoLineTable
      columns={columns}
      rows={rows}
      loading={loading}
      emptyMessage={{
        icon: 'fas fa-inbox',
        title: 'Không có phiếu yêu cầu nào',
        description: 'Hãy tạo phiếu yêu cầu mới để bắt đầu',
      }}
      onIdClick={onView}
      expandableActions={true}
      isMobile={isMobile}
    />
  );
};
